def empty(l):
	return len(l) == 0

def lucky_number(arr):
	st = []
	l = 0
	for d in arr:
		while not empty(st) and st[-1] < d:
			l = max(l, st.pop() ^ d)
		if not empty(st):
			l = max(l, st[-1] ^ d)
		st.append(d)
	d = 0
	if not empty(st):
		d = st.pop()
	while not empty(st):
		l = max(l, d ^ st[-1])
		d = st.pop()
	return l
N = int(input())
arr = list(map(int, input().split()))
print(lucky_number(arr))
